self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(CACHE);let i=0;await Promise.all(Array.from({length:8},async()=>{while(i<CORE.length){const path=CORE[i++];await cache.add(path);}}));await self.skipWaiting();})());});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('xiaoxiaowen-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{
 const req=event.request,url=new URL(req.url);if(req.method!=='GET')return;
 const local=url.origin===self.location.origin;
 const glyph=url.hostname==='cdn.jsdelivr.net'&&url.pathname.startsWith('/npm/hanzi-writer-data@2.0.1/');
 if(!local&&!glyph)return;
 if(req.mode==='navigate'){event.respondWith(fetch(req).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(c=>c.put('index.html',copy));}return response;}).catch(()=>caches.match('index.html')));return;}
 event.respondWith(caches.match(req).then(hit=>hit||fetch(req).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(c=>c.put(req,copy));}return response;})));
});
